    26→
    27→impl VerifierContext {
    28→    pub fn new(trusted_setup: &TrustedSetup) -> Self {
    29→        let verification_key = verification_key_from_setup(trusted_setup);
    30→
    31→        let multipoint_verifier = Verifier::new(
    32→            verification_key,
    33→            FIELD_ELEMENTS_PER_EXT_BLOB,
